// .github/workflows/performance-budget.yml
name: Performance Budget Check
on: [pull_request]
jobs:
  budget-check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v2
      - uses: actions/setup-node@v2
      - run: npm ci
      - run: npm run build
      - uses: andresz1/size-limit-action@v1
        with:
          github_token: ${{ secrets.GITHUB_TOKEN }}
          skip_step: install
          build_script: npm run build

// package.json
"size-limit": [
  {
    "path": "dist/*.js",
    "limit": "200 KB"
  },
  {
    "path": "dist/*.css",
    "limit": "50 KB"
  },
  {
    "path": "dist/**/*.png",
    "limit": "100 KB"
  }
]

// Budget monitoring with Web Vitals
import { onLCP, onCLS, onINP } from 'web-vitals';

const BUDGETS = {
  LCP: 2500, // 2.5s
  CLS: 0.05,
  INP: 200 // 200ms
};

function checkBudget(metric, value, budget) {
  if (value > budget) {
    console.error(`Budget exceeded: ${metric} (${value}ms > ${budget}ms)`);

    // Send to monitoring service
    fetch('/api/budget-violation', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ metric, value, budget, timestamp: Date.now() })
    });
  }
}

onLCP((metric) => checkBudget('LCP', metric.value, BUDGETS.LCP));
onCLS((metric) => checkBudget('CLS', metric.value, BUDGETS.CLS));
onINP((metric) => checkBudget('INP', metric.value, BUDGETS.INP));
